<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Billiards</title>
<style>
  html, body {
    margin: 0; padding: 0;
    background: #1a1410;
    color: #e8e0d0;
    font-family: -apple-system, Segoe UI, Roboto, sans-serif;
    display: flex; flex-direction: column;
    align-items: center; min-height: 100vh;
  }
  h1 { font-weight: 500; margin: 16px 0 4px; letter-spacing: 1px; }
  #wrap { position: relative; }
  canvas {
    display: block;
    border-radius: 8px;
    box-shadow: 0 12px 40px rgba(0,0,0,.6);
    touch-action: none;
  }
  #bar {
    display: flex; align-items: center; gap: 16px;
    margin: 12px 0 4px;
  }
  button {
    background: #3a5a3a; color: #eafbea;
    border: 1px solid #557055; border-radius: 6px;
    padding: 8px 18px; font-size: 15px; cursor: pointer;
  }
  button:hover { background: #487048; }
  #hint {
    font-size: 13px; color: #b8b0a0; max-width: 760px;
    text-align: center; line-height: 1.5; margin: 4px 0 24px;
  }
  #status { font-size: 14px; color: #d8cfa8; min-width: 120px; }
</style>
</head>
<body>
  <h1>◦ Billiards ◦</h1>
  <div id="wrap">
    <canvas id="cv" width="800" height="440"></canvas>
  </div>
  <div id="bar">
    <button id="reset">Reset / Rack</button>
    <span id="status">Ready</span>
  </div>
  <div id="hint">
    <b>How to shoot:</b> Press and hold on the white cue ball, drag <i>backwards</i>
    (away from the direction you want it to go), and <b>release</b> to strike.
    The further you drag, the harder the shot — the aim line shows your aim.
  </div>

<script>
(function () {
  "use strict";

  const canvas = document.getElementById("cv");
  const ctx = canvas.getContext("2d");
  const statusEl = document.getElementById("status");

  // ---- Table geometry ----
  const W = 800;          // playfield width
  const H = 440;          // playfield height
  const R = 11;           // ball radius
  const POCKET_R = 20;    // pocket capture radius
  const CUSHION = 26;     // visual rail thickness (playfield is inset by this in the canvas)

  // Physics constants
  const FRICTION = 260;       // px/s^2 deceleration (rolling resistance)
  const STOP_SPEED = 3;       // px/s below which a ball is snapped to rest
  const REST_ELASTIC = 0.985; // wall/ball restitution (near-elastic)
  const SUBSTEP = 1 / 480;    // fixed physics sub-step for determinism

  // Pocket centres (in playfield coords: 0..W, 0..H)
  const pockets = [
    { x: 0,   y: 0 }, { x: W,   y: 0 },
    { x: 0,   y: H }, { x: W,   y: H },
    { x: W/2, y: 0 }, { x: W/2, y: H }, // middle of the long (horizontal) rails
  ];

  // Ball colours for the rack
  const COLORS = [
    "#ffffff", // cue
    "#f4c20d", "#0b5cd8", "#d81b1b", "#7a1fa2",
    "#e8760a", "#0a8043", "#7a2e0a", "#111111",
    "#f4c20d", "#0b5cd8", "#d81b1b", "#7a1fa2",
    "#e8760a", "#0a8043",
  ];

  // ---- Ball state ----
  // Each ball: {x, y, vx, vy, potted, cue, color}
  let balls = [];

  function makeBall(spec, i) {
    return {
      x: spec.x, y: spec.y,
      vx: spec.vx || 0, vy: spec.vy || 0,
      potted: false,
      cue: !!spec.cue,
      color: spec.color || COLORS[i % COLORS.length] || "#cccccc",
    };
  }

  function reset(spec) {
    balls = spec.map(makeBall);
    draw();
  }

  // Standard triangle rack (15 balls) + cue ball
  function defaultRack() {
    const arr = [];
    // cue ball on the "head spot" (left quarter)
    arr.push({ x: W * 0.25, y: H / 2, cue: true, color: "#ffffff" });

    // triangle apex near the right foot spot
    const apexX = W * 0.68;
    const apexY = H / 2;
    const dx = R * 2 * Math.cos(Math.PI / 6) + 0.5; // row spacing
    const dy = R * 2 + 0.5;                          // within-row spacing
    let idx = 1;
    for (let row = 0; row < 5; row++) {
      const cx = apexX + row * dx;
      const startY = apexY - row * (dy / 2);
      for (let k = 0; k <= row; k++) {
        arr.push({
          x: cx, y: startY + k * dy,
          color: COLORS[idx] || "#cccccc",
        });
        idx++;
      }
    }
    return arr;
  }

  // ---- Physics ----
  function step(dt) {
    if (dt <= 0) return;
    let remaining = dt;
    while (remaining > 1e-9) {
      const h = Math.min(SUBSTEP, remaining);
      integrate(h);
      remaining -= h;
    }
    draw();
  }

  function integrate(h) {
    // 1. Move + friction
    for (const b of balls) {
      if (b.potted) continue;
      const sp = Math.hypot(b.vx, b.vy);
      if (sp > 0) {
        // linear friction deceleration
        const drop = FRICTION * h;
        let ns = sp - drop;
        if (ns < STOP_SPEED) ns = 0;
        const scale = ns / sp;
        b.vx *= scale;
        b.vy *= scale;
      }
      b.x += b.vx * h;
      b.y += b.vy * h;
    }

    // 2. Cushions (walls) — reflect and clamp
    for (const b of balls) {
      if (b.potted) continue;
      if (b.x < R)     { b.x = R;     b.vx = Math.abs(b.vx) * REST_ELASTIC; }
      if (b.x > W - R) { b.x = W - R; b.vx = -Math.abs(b.vx) * REST_ELASTIC; }
      if (b.y < R)     { b.y = R;     b.vy = Math.abs(b.vy) * REST_ELASTIC; }
      if (b.y > H - R) { b.y = H - R; b.vy = -Math.abs(b.vy) * REST_ELASTIC; }
    }

    // 3. Ball-to-ball collisions (equal mass, near-elastic, along line of centres)
    for (let i = 0; i < balls.length; i++) {
      const a = balls[i];
      if (a.potted) continue;
      for (let j = i + 1; j < balls.length; j++) {
        const b = balls[j];
        if (b.potted) continue;
        let dx = b.x - a.x;
        let dy = b.y - a.y;
        let dist = Math.hypot(dx, dy);
        const min = R * 2;
        if (dist > 0 && dist < min) {
          // normalise
          const nx = dx / dist;
          const ny = dy / dist;
          // positional correction (split the overlap)
          const overlap = (min - dist) / 2;
          a.x -= nx * overlap; a.y -= ny * overlap;
          b.x += nx * overlap; b.y += ny * overlap;

          // relative velocity along normal
          const rvx = b.vx - a.vx;
          const rvy = b.vy - a.vy;
          const vn = rvx * nx + rvy * ny;
          if (vn < 0) { // approaching
            // equal mass elastic: exchange normal components (scaled by restitution)
            const imp = -vn * REST_ELASTIC;
            a.vx -= imp * nx; a.vy -= imp * ny;
            b.vx += imp * nx; b.vy += imp * ny;
          }
        } else if (dist === 0) {
          // perfectly overlapping — nudge deterministically apart
          a.x -= R; b.x += R;
        }
      }
    }

    // 4. Pockets
    for (const b of balls) {
      if (b.potted) continue;
      for (const p of pockets) {
        if (Math.hypot(b.x - p.x, b.y - p.y) <= POCKET_R) {
          b.potted = true;
          b.vx = 0; b.vy = 0;
          break;
        }
      }
    }
  }

  function state() {
    return balls.map(b => ({
      x: b.x, y: b.y, vx: b.vx, vy: b.vy,
      potted: b.potted, cue: b.cue,
    }));
  }

  function anyMoving() {
    for (const b of balls) {
      if (!b.potted && (Math.abs(b.vx) > 0 || Math.abs(b.vy) > 0)) return true;
    }
    return false;
  }

  // ---- Shooting ----
  function findCue() {
    return balls.find(b => b.cue && !b.potted) || null;
  }

  function shoot(vx, vy) {
    const cue = findCue();
    if (!cue) return;
    cue.vx = vx;
    cue.vy = vy;
  }

  // ---- Rendering ----
  // Canvas is playfield inset by CUSHION on all sides for the rails.
  function toCanvas(px, py) {
    return { x: px + CUSHION, y: py + CUSHION };
  }
  function toPlay(cx, cy) {
    return { x: cx - CUSHION, y: cy - CUSHION };
  }

  function draw() {
    const cw = canvas.width, chh = canvas.height;

    // outer rail (wood)
    ctx.fillStyle = "#5a3a1a";
    roundRect(0, 0, cw, chh, 10);
    ctx.fill();

    // felt
    ctx.fillStyle = "#137a3a";
    ctx.fillRect(CUSHION, CUSHION, W, H);

    // subtle felt gradient
    const g = ctx.createRadialGradient(cw/2, chh/2, 60, cw/2, chh/2, cw*0.7);
    g.addColorStop(0, "rgba(255,255,255,0.06)");
    g.addColorStop(1, "rgba(0,0,0,0.18)");
    ctx.fillStyle = g;
    ctx.fillRect(CUSHION, CUSHION, W, H);

    // cushion inner bevel
    ctx.strokeStyle = "rgba(0,0,0,0.35)";
    ctx.lineWidth = 3;
    ctx.strokeRect(CUSHION, CUSHION, W, H);

    // pockets
    for (const p of pockets) {
      const c = toCanvas(p.x, p.y);
      ctx.beginPath();
      ctx.arc(c.x, c.y, POCKET_R, 0, Math.PI * 2);
      ctx.fillStyle = "#0a0a0a";
      ctx.fill();
      ctx.strokeStyle = "#241a10";
      ctx.lineWidth = 3;
      ctx.stroke();
    }

    // balls
    for (const b of balls) {
      if (b.potted) continue;
      const c = toCanvas(b.x, b.y);
      // shadow
      ctx.beginPath();
      ctx.arc(c.x + 2, c.y + 3, R, 0, Math.PI * 2);
      ctx.fillStyle = "rgba(0,0,0,0.25)";
      ctx.fill();
      // body
      ctx.beginPath();
      ctx.arc(c.x, c.y, R, 0, Math.PI * 2);
      ctx.fillStyle = b.color;
      ctx.fill();
      // highlight
      ctx.beginPath();
      ctx.arc(c.x - R*0.32, c.y - R*0.32, R*0.35, 0, Math.PI * 2);
      ctx.fillStyle = "rgba(255,255,255,0.45)";
      ctx.fill();
      // outline
      ctx.beginPath();
      ctx.arc(c.x, c.y, R, 0, Math.PI * 2);
      ctx.strokeStyle = "rgba(0,0,0,0.35)";
      ctx.lineWidth = 1;
      ctx.stroke();
    }

    // aim line while dragging
    if (aiming && dragStart) {
      const cue = findCue();
      if (cue) {
        const c = toCanvas(cue.x, cue.y);
        // direction = from current drag point toward cue (i.e. opposite of drag)
        const dx = c.x - dragCur.x;
        const dy = c.y - dragCur.y;
        const len = Math.hypot(dx, dy);
        if (len > 2) {
          const ux = dx / len, uy = dy / len;
          const power = Math.min(len, MAX_DRAG);
          // aim line forward
          ctx.beginPath();
          ctx.moveTo(c.x, c.y);
          ctx.lineTo(c.x + ux * (60 + power), c.y + uy * (60 + power));
          ctx.strokeStyle = "rgba(255,255,255,0.85)";
          ctx.lineWidth = 2;
          ctx.setLineDash([6, 6]);
          ctx.stroke();
          ctx.setLineDash([]);
          // drag/power indicator (behind cue)
          ctx.beginPath();
          ctx.moveTo(c.x, c.y);
          ctx.lineTo(c.x - ux * power, c.y - uy * power);
          ctx.strokeStyle = "rgba(255,120,120,0.8)";
          ctx.lineWidth = 3;
          ctx.stroke();
          // power meter
          const frac = power / MAX_DRAG;
          ctx.fillStyle = "rgba(255,255,255,0.15)";
          ctx.fillRect(CUSHION, chh - 8, W, 5);
          ctx.fillStyle = `rgb(${Math.round(120 + 135*frac)}, ${Math.round(200 - 150*frac)}, 60)`;
          ctx.fillRect(CUSHION, chh - 8, W * frac, 5);
        }
      }
    }
  }

  function roundRect(x, y, w, h, r) {
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.arcTo(x + w, y, x + w, y + h, r);
    ctx.arcTo(x + w, y + h, x, y + h, r);
    ctx.arcTo(x, y + h, x, y, r);
    ctx.arcTo(x, y, x + w, y, r);
    ctx.closePath();
  }

  // ---- Mouse aiming ----
  const MAX_DRAG = 240;      // px of drag = max power
  const MAX_SPEED = 1500;    // px/s at max power
  let aiming = false;
  let dragStart = null;      // canvas coords where press began
  let dragCur = null;

  function canvasPos(e) {
    const rect = canvas.getBoundingClientRect();
    const sx = canvas.width / rect.width;
    const sy = canvas.height / rect.height;
    const cx = (e.clientX - rect.left) * sx;
    const cy = (e.clientY - rect.top) * sy;
    return { x: cx, y: cy };
  }

  canvas.addEventListener("pointerdown", (e) => {
    if (anyMoving()) return; // wait for table to settle
    const pos = canvasPos(e);
    const cue = findCue();
    if (!cue) return;
    const c = toCanvas(cue.x, cue.y);
    const d = Math.hypot(pos.x - c.x, pos.y - c.y);
    if (d <= R * 2.5) {
      aiming = true;
      dragStart = pos;
      dragCur = pos;
      canvas.setPointerCapture(e.pointerId);
      statusEl.textContent = "Aiming…";
      draw();
    }
  });

  canvas.addEventListener("pointermove", (e) => {
    if (!aiming) return;
    dragCur = canvasPos(e);
    draw();
  });

  canvas.addEventListener("pointerup", (e) => {
    if (!aiming) return;
    aiming = false;
    const cue = findCue();
    if (cue) {
      const c = toCanvas(cue.x, cue.y);
      // shoot in direction opposite to the drag (drag back to pull)
      const dx = c.x - dragCur.x;
      const dy = c.y - dragCur.y;
      const len = Math.hypot(dx, dy);
      if (len > 4) {
        const power = Math.min(len, MAX_DRAG) / MAX_DRAG; // 0..1
        const ux = dx / len, uy = dy / len;
        const speed = power * MAX_SPEED;
        shoot(ux * speed, uy * speed);
        statusEl.textContent = "Shot!";
      } else {
        statusEl.textContent = "Ready";
      }
    }
    dragStart = null;
    draw();
  });

  canvas.addEventListener("pointercancel", () => {
    aiming = false; dragStart = null; draw();
  });

  // ---- Animation loop ----
  let running = true;
  let lastT = null;

  function loop(t) {
    if (!running) return;
    if (lastT == null) lastT = t;
    let dt = (t - lastT) / 1000;
    lastT = t;
    if (dt > 0.05) dt = 0.05; // clamp big frame gaps
    if (dt > 0) step(dt);
    if (!aiming) {
      statusEl.textContent = anyMoving() ? "Rolling…" : "Ready";
    }
    rafId = requestAnimationFrame(loop);
  }

  let rafId = null;
  function pause() {
    running = false;
    if (rafId != null) { cancelAnimationFrame(rafId); rafId = null; }
  }
  function resume() {
    if (running) return;
    running = true;
    lastT = null;
    rafId = requestAnimationFrame(loop);
  }

  // ---- Controls ----
  document.getElementById("reset").addEventListener("click", () => {
    reset(defaultRack());
    statusEl.textContent = "Ready";
  });

  // ---- Expose contract ----
  window.sim = {
    W, H, R,
    reset, step, state, shoot, pause, resume,
  };

  // ---- Boot ----
  reset(defaultRack());
  rafId = requestAnimationFrame(loop);
})();
</script>
</body>
</html>
